import{_ as d,o as e,c as o,a2 as a}from"./chunks/framework.Bg-Zxr5O.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Matrix-Expressions.md","filePath":"manual-zh/Matrix-Expressions.md","lastUpdated":1785684581000}'),c={name:"manual-zh/Matrix-Expressions.md"};function i(r,t,l,s,n,p){return e(),o("div",null,[...t[0]||(t[0]=[a('<h4 id="_16-4-1-矩阵表达式" tabindex="-1">16.4.1 矩阵表达式 <a class="header-anchor" href="#_16-4-1-矩阵表达式" aria-label="Permalink to &quot;16.4.1 矩阵表达式&quot;">​</a></h4><p>许多矩阵命令使用表达式。矩阵表达式可以使用下列运算符，按运算符优先级从高到低列出。在同一优先级内，运算符按从左到右的顺序结合。</p><ul><li>函数调用 <code>()</code> 与矩阵构造 <code>{}</code></li><li>索引 <code>()</code></li><li>一元 <code>+</code> 和 <code>-</code></li><li>整数序列 <code>:</code></li><li>乘方 <code>**</code> 和 <code>&amp;**</code></li><li>乘法 <code>*</code> 和 <code>&amp;*</code>，以及除法 <code>/</code> 和 <code>&amp;/</code></li><li>加法 <code>+</code> 和减法 <code>-</code></li><li>关系运算符 <code>&lt; &lt;= = &gt;= &gt; &lt;&gt;</code></li><li>逻辑 <code>NOT</code></li><li>逻辑 <code>AND</code></li><li>逻辑 <code>OR</code> 和 <code>XOR</code></li></ul><p>可用的矩阵函数见 <a href="./Matrix-Functions">Matrix Functions</a>。其余运算符在下面有更详细的说明。</p><p>表达式在矩阵语言中出现的一些场合下，可能会产生歧义：究竟是 “/” 作为运算符，还是作为子命令之间的分隔符。在这些场合下，只允许使用优先级高于 “/” 的运算符出现在括号之外。后续章节将这些称为 <em>受限表达式</em>。</p><table tabindex="0"><thead><tr><th>• 矩阵构造运算符 {}</th><th></th><th></th></tr></thead><tbody><tr><td>• 整数序列运算符 ‘ : ’</td><td></td><td></td></tr><tr><td>• 索引运算符 ()</td><td></td><td></td></tr><tr><td>• 一元运算符</td><td></td><td></td></tr><tr><td>• 逐元素二元运算符</td><td></td><td></td></tr><tr><td>• 矩阵乘法运算符 ‘ * ’</td><td></td><td></td></tr><tr><td>• 矩阵乘方运算符 **</td><td></td><td></td></tr></tbody></table>',6)])])}const m=d(c,[["render",i]]);export{h as __pageData,m as default};
